// Presentation acceptance only: isolated synthetic storage, all Supabase traffic blocked.
const fs=require('node:fs'),path=require('node:path'),{chromium,webkit}=require('playwright'),XLSX=require('xlsx'),seed=require('./ui-fixture.cjs');
const url=process.env.PREVIEW_URL;if(!url)throw Error('PREVIEW_URL required');
const output=path.join(process.env.AUDIT_OUTPUT||'responsive-audit-output','physical-iphone-III');fs.mkdirSync(output,{recursive:true});
const matrix={},evidence={},screenshots=[],animations=[],errors=[],isolationErrors=[];
async function run(browser,engine,device,width,height){
 const prefix=engine+'.'+device,dir=path.join(output,prefix);fs.mkdirSync(dir,{recursive:true});let context,page;
 const check=(name,ok,data)=>{matrix[prefix+'.'+name]=ok?'PASS':'FAIL';if(data!==undefined)evidence[prefix+'.'+name]=data;console.log(prefix+'.'+name+' '+(ok?'PASS':'FAIL')+(ok?'':' '+JSON.stringify(data)));};
 async function fresh(role,wait=true,reducedMotion='no-preference'){
  await context?.close();context=await browser.newContext({viewport:{width,height},deviceScaleFactor:1,hasTouch:device!=='desktop',locale:'de-CH',timezoneId:'Europe/Zurich',reducedMotion,...(device==='iphone'&&!wait&&!process.env.DOM_ONLY?{recordVideo:{dir:path.join(dir,'video'),size:{width,height}}}:{})});
  await context.addInitScript(({seedSource})=>{(0,eval)('('+seedSource+')')();if(sessionStorage.getItem('iii-long-success-note')){const key='ambassador-breakfast-rooms',state=JSON.parse(localStorage.getItem(key));state.rooms.find(r=>r.room===21).note='Synthetische Bemerkung: Hafermilch bevorzugt. Frühstück morgen um 08:30. Fensterplatz, wenn möglich. Bitte glutenfreies Brot und ungesüssten Tee bereitstellen. Diese zusätzlichen Zeilen prüfen ausschließlich, ob der gesamte Bemerkungsblock oberhalb des Footers erreichbar bleibt.';localStorage.setItem(key,JSON.stringify(state));}},{seedSource:seed.toString()});
  await context.addInitScript(()=>{window.__entryTrace=[];let seen=false;new MutationObserver(()=>{const el=document.querySelector('.work-area-entry-transition');if(el&&!seen){seen=true;window.__entryTrace.push({event:'start',time:performance.now(),role:el.dataset.workArea,duration:getComputedStyle(el).animationDuration,pointer:getComputedStyle(el).pointerEvents});}else if(!el&&seen&&window.__entryTrace.length===1)window.__entryTrace.push({event:'end',time:performance.now()});}).observe(document,{subtree:true,childList:true,attributes:true,attributeFilter:['class']});});
  await context.route('**/*',r=>/supabase/i.test(r.request().url())||new URL(r.request().url()).hostname==='vercel.live'?r.abort():r.continue());
  page=await context.newPage();page.setDefaultTimeout(12000);page.on('pageerror',e=>{const v={prefix,message:e.message};if(/supabase\.co/.test(e.message)&&/access control checks/.test(e.message))isolationErrors.push(v);else errors.push(v);});
  await page.goto(url,{waitUntil:'domcontentloaded'});await page.locator('.role-selection').waitFor();
  if(role){await page.locator('.role-selection [data-role="'+role+'"]').click();await page.locator('.app-shell').waitFor();if(wait)await page.locator('.work-area-entry-transition').waitFor({state:'detached'});}
 }
 async function shot(name,data){if(!process.env.DOM_ONLY){const file=path.join(dir,name+'.png');await page.screenshot({path:file,animations:name.includes('transition-frame')?'allow':'disabled'});screenshots.push({file,engine,device,state:name,viewport:[width,height],metrics:data,synthetic:true,realDataMutation:false,testFixtureOnly:name.includes('fixture')});}const m=await page.evaluate(()=>({width:innerWidth,height:innerHeight,scrollWidth:document.documentElement.scrollWidth}));check('overflow.'+name,m.scrollWidth<=m.width,m);}
 async function section(name,fn){try{await fn();}catch(e){check(name,false,{error:String(e)});await shot('FAIL-'+name).catch(()=>{});}}
 async function modal(sel){return page.locator(sel).evaluate(e=>{const r=e=>e?.getBoundingClientRect().toJSON(),css=e=>getComputedStyle(e),body=e.querySelector(':scope > .modal-body,:scope > .service-success-body'),head=e.querySelector(':scope > .modal-head,:scope > .service-success-head'),foot=e.querySelector(':scope > .modal-actions,:scope > .service-success-footer,:scope > .reception-view-actions'),hit=e=>{const b=r(e);return e.contains(document.elementFromPoint(b.x+b.width/2,b.y+b.height/2));},close=head?.querySelector('button'),background=document.querySelector('.topbar');return{modal:r(e),head:r(head),body:r(body),footer:r(foot),headerBorder:head&&css(head).borderBottomWidth,headerColor:head&&css(head).borderBottomColor,footerBorder:foot&&css(foot).borderTopWidth,footerColor:foot&&css(foot).borderTopColor,footerHeight:foot?.offsetHeight,footerContentWidth:foot?foot.clientWidth-parseFloat(css(foot).paddingLeft)-parseFloat(css(foot).paddingRight):null,buttons:foot?[...foot.querySelectorAll('button')].map(b=>({box:r(b),hit:hit(b)})):[],closeHit:close?hit(close):null,background:r(background),backgroundVisible:r(background).bottom<=r(e).top,backgroundInert:background.inert,scrollHeight:body?.scrollHeight,clientHeight:body?.clientHeight,scrollTop:body?.scrollTop,last:r(body?.lastElementChild),radius:css(e).borderRadius,scrollAreas:[e.parentElement,e,body,...body.querySelectorAll('*')].filter(x=>x.scrollHeight>x.clientHeight+1&&/(auto|scroll)/.test(css(x).overflowY)).map(x=>x.className)};});}
 async function chrome(name,m){check(name+'.separators',m.headerBorder==='1px'&&m.footerBorder==='1px'&&m.headerColor==='rgb(220, 227, 225)'&&m.footerColor==='rgb(220, 227, 225)',m);check(name+'.body-footer',m.body.top>=m.head.bottom-.5&&m.body.bottom<=m.footer.top+.5&&m.footer.bottom<=m.modal.bottom+.5&&m.buttons.every(b=>b.hit),m);}
 async function dateMetrics(){return page.locator('.guest-edit-modal').evaluate(e=>{const r=e=>e.getBoundingClientRect().toJSON(),css=e=>getComputedStyle(e);return{dates:[...e.querySelectorAll('input[type=date]')].map(i=>({input:r(i),label:r(i.parentElement),title:r(i.parentElement.querySelector('span')),border:css(i.parentElement).borderWidth,padding:css(i.parentElement).padding,inputBorder:css(i).borderWidth,value:i.value})),fieldHit:(()=>{const f=e.querySelector('textarea'),b=r(f);return f.contains(document.elementFromPoint(b.x+b.width/2,b.y+b.height/2));})(),pickerLayers:e.querySelectorAll('.guest-info-picker-layer').length};});}
 async function editor(role){await fresh(role);if(role==='service'){await page.getByRole('button',{name:'Zimmer 20 öffnen'}).click();await page.locator('.guest-info-edit-link').click();await page.locator('.guest-modal > .modal-actions button').click();await page.getByRole('button',{name:'Gäste bearbeiten',exact:true}).click();await page.getByRole('button',{name:'Zimmer 20 öffnen'}).click();}else{await page.getByRole('button',{name:'Zimmer 21 öffnen'}).click();await page.locator('.reception-view-actions button').click();}await page.locator('.guest-edit-modal:not(.reception-view-mode)').waitFor();}
 try{
  await section('main-headers',async()=>{for(const role of ['service','reception']){await fresh(role);const m=await page.locator('.topbar').evaluate(e=>({border:getComputedStyle(e).borderBottomWidth,shadow:getComputedStyle(e).boxShadow}));check(role+'.global-header-no-line',m.border==='0px'&&m.shadow==='none',m);if(role==='reception'){const a=await page.evaluate(()=>{const r=s=>document.querySelector(s).getBoundingClientRect().toJSON();return{actions:r('.reception-actions'),search:r('.search-box'),list:r('.ipad-room-grid'),buttons:[...document.querySelectorAll('.reception-actions button')].map(e=>e.getBoundingClientRect().toJSON())};});if(device==='iphone')check('mobile-actions.content-axis',Math.abs(a.actions.left-a.search.left)<.5&&Math.abs(a.actions.right-a.search.right)<.5&&a.actions.left===a.list.left&&a.actions.right===a.list.right&&a.buttons.every(b=>b.height===44)&&Math.abs(a.buttons[0].width-a.buttons[1].width)<.5&&a.buttons[0].top===a.buttons[1].top,a);}await shot(role==='service'?'01-service-main':'02-reception-main');}});
  await section('animation',async()=>{if(device!=='iphone')return;const durations={};for(const role of ['service','reception']){await fresh(role,false);await page.waitForFunction(()=>window.__entryTrace.length);for(const t of [650,2200,4000]){await page.waitForFunction(t=>performance.now()-window.__entryTrace[0].time>=t,t);const data=await page.evaluate(()=>({now:performance.now(),trace:window.__entryTrace,opacity:getComputedStyle(document.querySelector('.work-area-entry-transition')).opacity}));await shot(role+'-transition-frame-'+t,data);}await page.waitForFunction(()=>window.__entryTrace.length===2);const trace=await page.evaluate(()=>__entryTrace);durations[role]=trace[1].time-trace[0].time;const video=page.video();await page.close();if(video){const file=path.join(dir,role+'-entry-transition.webm');await video.saveAs(file);fs.unlinkSync(await video.path());}animations.push({engine,device,role,trace,effectiveMs:durations[role]});check(role+'.transition-duration',durations[role]>=4600&&durations[role]<=5200&&trace[0].pointer==='none',{trace,effectiveMs:durations[role]});}check('transition-equal-duration',Math.abs(durations.service-durations.reception)<120,durations);for(const role of ['service','reception']){await fresh(role,true,'reduce');const trace=await page.evaluate(()=>__entryTrace);check(role+'.reduced-motion',trace.length===2&&trace[1].time-trace[0].time<500,trace);}});
  await section('success',async()=>{await fresh('service');await page.evaluate(()=>{sessionStorage.setItem('iii-long-success-note','1');});await page.reload({waitUntil:'domcontentloaded'});await page.locator('.app-shell').waitFor();await page.getByRole('button',{name:'Zimmer 21 öffnen'}).click();await page.locator('.table-picker').getByRole('button',{name:'17',exact:true}).click();await page.locator('.checkin-choice-modal .modal-actions .primary').filter({hasText:'17'}).click();await page.locator('.service-success-body').waitFor();const top=await modal('.checkin-card');await chrome('success',top);check('success.context',top.backgroundVisible&&top.backgroundInert&&top.modal.left>=10&&top.radius==='16px',top);await shot('03-success-note-top',top);await page.locator('.service-success-body').evaluate(e=>e.scrollTop=e.scrollHeight);const end=await modal('.checkin-card'),note=await page.locator('.checkin-card .important-note').evaluate(e=>({block:e.getBoundingClientRect().toJSON(),text:e.querySelector('p').getBoundingClientRect().toJSON(),content:e.textContent}));check('success.complete-last-note',(device!=='iphone'||end.scrollTop>0)&&note.block.top>=end.body.top-.5&&note.block.bottom<=end.footer.top-20&&note.text.bottom<=end.footer.top-20&&Math.abs(end.footer.top-top.footer.top)<.5,{...end,note});await shot('04-success-note-bottom',{...end,note});});
  await section('import',async()=>{await fresh('reception');const wb=XLSX.utils.book_new();const rows=[['Space number','Customer','Companions','Products'],...[20,30,40,50,60].flatMap(n=>Array.from({length:9},(_,i)=>n+i)).filter(n=>n!==55).map(n=>[n,'Audit Importgast '+n,'1 People 26.09.2026 - 30.09.2026','Continental'])];XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(rows),'Customers');await page.locator('input[type=file]').first().setInputFiles({name:'synthetic-III.xlsx',mimeType:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',buffer:XLSX.write(wb,{type:'buffer',bookType:'xlsx'})});await page.locator('.import-modal > .modal-actions').waitFor();const top=await modal('.import-modal');await chrome('import',top);check('import.modal-context',top.backgroundVisible&&top.backgroundInert&&top.modal.left>=10&&top.modal.right<=width-10&&top.modal.top>=80&&top.modal.bottom<=height-11&&top.radius==='16px'&&top.closeHit,top);check('import.one-scroll-body',top.scrollAreas.length===1&&top.scrollAreas[0]==='modal-body',top);await shot('05-import-top',top);await page.locator('.import-modal > .modal-body').evaluate(e=>e.scrollTop=e.scrollHeight);const bottom=await modal('.import-modal'),last=await page.locator('.import-list > div').last().evaluate(e=>({box:e.getBoundingClientRect().toJSON(),text:e.textContent}));check('import.last-row-above-footer',last.box.bottom<=bottom.footer.top-20&&last.box.top>=bottom.body.top&&Math.abs(bottom.footer.top-top.footer.top)<.5&&Math.abs(bottom.head.top-top.head.top)<.5,{...bottom,last});check('import.footer-half',bottom.buttons.length===2&&Math.abs(bottom.buttons[0].box.width-bottom.buttons[1].box.width)<.5&&bottom.buttons.every(b=>b.hit),bottom);await shot('06-import-bottom',{...bottom,last});await page.locator('.import-modal .close-button').click();await page.waitForFunction(()=>!document.querySelector('.topbar').inert);check('import.close-restores-context',await page.getByRole('button',{name:'Zimmer 21 öffnen'}).isVisible());});
  for(const role of device==='desktop'?['reception']:['reception','service'])await section(role+'-editor',async()=>{await editor(role);const m=await dateMetrics();const [a,b]=m.dates;check(role+'.date-single-control',m.dates.length===2&&m.dates.every(d=>d.border==='0px'&&d.padding==='0px'&&d.inputBorder==='1px')&&Math.abs(a.input.width-b.input.width)<.5&&a.input.height===b.input.height&&a.input.top===b.input.top&&b.label.left-a.label.right===16&&a.title.top===b.title.top,m);check(role+'.date-values-unchanged',a.value==='2026-09-26'&&b.value==='2026-09-30',m);const top=await modal('.guest-edit-modal');await chrome(role+'.editor',top);check(role+'.editor-no-picker',m.pickerLayers===0&&m.fieldHit&&top.closeHit,m);await shot(role==='service'?'08-service-edit-dates':'07-reception-edit-dates',m);await page.locator('.guest-edit-modal > .modal-body').evaluate(e=>e.scrollTop=e.scrollHeight);const end=await modal('.guest-edit-modal');check(role+'.editor-scroll',end.last.bottom<=end.footer.top&&Math.abs(top.footer.top-end.footer.top)<.5,end);await shot(role+'-edit-bottom',end);
  if(role==='reception'&&device==='iphone'){
   const persisted=await page.evaluate(()=>localStorage.getItem('ambassador-breakfast-rooms'));
   await page.locator('.remark-edit-summary').evaluate(e=>{e.dataset.syntheticUiFixture='multiple-remarks';e.innerHTML='<small style="display:block;color:#747d7a;margin-bottom:12px">TESTFIXTURE · keine Speicherfunktion</small><h3 style="margin:0;font-size:14px">Bemerkungen</h3>'+['Hafermilch bevorzugt','Frühstück morgen um 08:30','Fensterplatz, wenn möglich'].map(t=>'<p style="margin:0;padding:14px 0;border-bottom:1px solid #dce3e1;font-size:14px">'+t+'</p>').join('')+'<button type="button" style="margin-top:12px;min-height:44px;width:100%;background:white;border:1px solid #dce3e1;border-radius:10px;color:#1c777b">+ Bemerkung hinzufügen</button>';});await page.locator('.guest-edit-modal > .modal-body').evaluate(e=>e.scrollTop=0);await shot('09-fixture-multiple-notes-top');await page.locator('.guest-edit-modal > .modal-body').evaluate(e=>e.scrollTop=e.scrollHeight);const f=await modal('.guest-edit-modal');check('fixture.notes-footer',f.last.bottom<=f.footer.top-20&&f.scrollAreas.length===1&&await page.locator('[data-synthetic-ui-fixture] p').count()===3,f);check('fixture.no-persistence',persisted===await page.evaluate(()=>localStorage.getItem('ambassador-breakfast-rooms')));await shot('10-fixture-multiple-notes-bottom',f);
  }});
  await section('single-footers',async()=>{for(const role of ['reception','service']){await fresh(role);await page.getByRole('button',{name:'Zimmer 20 öffnen'}).click();const s=role==='service'?'.guest-modal:not(.guest-edit-modal) > .modal-actions':'.reception-view-actions';const m=await page.locator(s).evaluate(e=>{const css=getComputedStyle(e);return{width:e.clientWidth-parseFloat(css.paddingLeft)-parseFloat(css.paddingRight),buttons:[...e.children].map(b=>b.getBoundingClientRect().toJSON())};});check(role+'.single-footer-fullwidth',m.buttons.length===1&&Math.abs(m.buttons[0].width-m.width)<.5,m);await shot(role==='service'?'12-service-detail-close':'11-reception-detail-edit',m);}});
  if(device!=='desktop')await section('frozen-work-modals',async()=>{await fresh('service');await page.getByRole('button',{name:'Zimmer 21 öffnen'}).click();let m=await modal('.checkin-choice-modal');check('frozen.checkin-context',m.backgroundVisible&&m.backgroundInert&&m.radius==='16px'&&m.closeHit,m);if(device==='iphone')check('frozen.checkin-bounds',m.modal.top===80&&m.modal.left===12&&m.modal.width===366,m);await shot('13-checkin-regression',m);await page.locator('.checkin-choice-modal .close-button').click();await page.getByRole('button',{name:'Menü öffnen'}).click();await page.locator('[data-menu-action=special-guests]').click();m=await modal('.special-guest-modal');check('frozen.special-context',m.backgroundVisible&&m.backgroundInert&&m.radius==='16px'&&m.closeHit,m);await shot('14-special-regression',m);});
 }finally{await context?.close();}
}
(async()=>{for(const engine of(process.env.III_ENGINES||'webkit,chromium').split(',')){let b;try{const local=engine==='chromium'&&process.env.LOCAL_CHROMIUM;b=await({webkit,chromium}[engine]).launch(local?{executablePath:process.env.LOCAL_CHROMIUM,args:require(process.env.LOCAL_CHROMIUM_PACKAGE).default.args.filter(a=>a!=='--single-process')}:{headless:true});for(const [d,w,h]of[['iphone',390,844],['ipad',1024,1366],['desktop',1440,900]])if(!process.env.RUN_DEVICES||process.env.RUN_DEVICES.split(',').includes(d))await run(b,engine,d,w,h);}catch(e){matrix[engine+'.runner']='FAIL';evidence[engine+'.runner']=String(e);}finally{await b?.close();}}
matrix['runtime-errors']=errors.length?'FAIL':'PASS';fs.writeFileSync(path.join(output,'results.json'),JSON.stringify({url,commit:process.env.SOURCE_SHA,matrix,evidence,screenshots,animations,errors,isolationErrors,conditions:{physicalSafariApproval:false,supabaseWrites:false,productionWrites:false,multipleRemarksAreTestFixtureOnly:true}},null,2));console.log(JSON.stringify({pass:Object.values(matrix).filter(v=>v==='PASS').length,fail:Object.values(matrix).filter(v=>v==='FAIL').length,screenshots:screenshots.length}));if(Object.values(matrix).includes('FAIL'))process.exitCode=1;})();
